const HEADERS = {
  "X-Content-Type-Options": "nosniff",
  "Referrer-Policy": "strict-origin-when-cross-origin",
  "X-Frame-Options": "DENY",
  "Content-Security-Policy": "default-src 'none'; script-src 'self' 'unsafe-inline' https://*.googletagmanager.com https://*.google-analytics.com https://connect.facebook.net; img-src 'self' https://*.google-analytics.com https://*.googletagmanager.com https://www.facebook.com; style-src 'self' 'unsafe-inline'; font-src 'self'; connect-src 'self' https://*.google-analytics.com https://*.analytics.google.com https://*.googletagmanager.com https://www.facebook.com https://connect.facebook.net; form-action 'self'; base-uri 'none'",
};

function pageHeaders(type) {
  return { ...HEADERS, "Content-Type": type, "Cache-Control": "no-store" };
}

function html(body) {
  return new Response(body, { headers: pageHeaders("text/html; charset=utf-8") });
}

function text(status, body) {
  return new Response(body, { status, headers: pageHeaders("text/plain; charset=utf-8") });
}

function clean(value) {
  return String(value || "").replace(/[\r\n]+/g, " ").trim();
}

function isEmail(value) {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value);
}

function field(form, name) {
  return clean(form.get(name));
}

function rawEmail(replyTo, subject, body) {
  return [
    "From: " + FROM_NAME + " <" + FROM + ">",
    "To: " + TO,
    "Reply-To: " + replyTo,
    "Subject: " + subject,
    "MIME-Version: 1.0",
    "Content-Type: text/plain; charset=utf-8",
    "Content-Transfer-Encoding: 8bit",
    "",
    body,
  ].join("\r\n");
}

async function sendMail(env, replyTo, subject, body) {
  const message = new EmailMessage(FROM, TO, rawEmail(replyTo, subject, body));
  await env.EMAIL.send(message);
}

function failPage() {
  return html("<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"><title>Please try again · Walton County Builders Network</title><link rel=\"stylesheet\" href=\"/styles.css\"><meta name=\"robots\" content=\"noindex, nofollow\"></head><body><main class=\"container\" style=\"padding:72px 0;max-width:36rem;\"><h1>We could not send that just now.</h1><p>Please try again in a moment.</p><p style=\"margin-top:24px;\"><a class=\"button\" href=\"/\">Back to the homepage</a></p></main></body></html>");
}

const CANONICAL_ORIGIN = "https://waltonbuildersnetwork.org";
const WWW_HOST = "www.waltonbuildersnetwork.org";
